def compare_runs(before, after):
    regressions = sorted(t for t, r in after.items() if r == 'fail' and before.get(t) == 'pass')
    fixed = sorted(t for t, r in after.items() if r == 'pass' and before.get(t) == 'fail')
    new = sorted(t for t in after if t not in before)
    return {'regressions': regressions, 'fixed': fixed, 'new': new}

